    my_def = me.count('D')
    last_opp = opp[-1]
    last_me = me[-1]

    if n == 99:
        return 'D'

    if opp_def == n:
        return 'D'

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'
    if n == 2:
        return 'D' if last_opp == 'D' else 'C'
    if n == 3:
        return 'D' if last_opp == 'D' else 'C'

